import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// Hand-written in-process double for the downstream pricing service.
const prices = { A: 10, B: 40, C: 9.99, D: 100, E: 100.5 }
const pricing = { priceOf: async (sku) => prices[sku] }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://127.0.0.1:${server.address().port}`
})
after(() => server.close())

const post = (body, raw) => fetch(`${base}/orders`, { method: 'POST', body: raw ?? JSON.stringify(body) })
const json = async (res) => ({ status: res.status, type: res.headers.get('content-type'), body: await res.json() })

// Order matters: the service keeps ids in a module-level counter.
test('POST /orders creates an order, id "1", no discount at or below 100', async () => {
  const r = await json(await post({ items: [{ sku: 'A', qty: 2 }] }))
  assert.deepEqual(r, { status: 201, type: 'application/json', body: { id: '1', items: [{ sku: 'A', qty: 2 }], total: 20 } })
})

test('POST /orders applies 10% discount above 100 and floors the total', async () => {
  const r = await json(await post({ items: [{ sku: 'B', qty: 3 }] }))
  assert.equal(r.status, 201)
  assert.equal(r.body.id, '2')
  assert.equal(r.body.total, 108)
})

test('POST /orders total of exactly 100 gets no discount', async () => {
  assert.equal((await json(await post({ items: [{ sku: 'D', qty: 1 }] }))).body.total, 100)
})

test('POST /orders floors fractional totals', async () => {
  assert.equal((await json(await post({ items: [{ sku: 'C', qty: 3 }] }))).body.total, 29)
  // 100.5 > 100 -> 90.45 -> 90
  assert.equal((await json(await post({ items: [{ sku: 'E', qty: 1 }] }))).body.total, 90)
})

test('POST /orders sums several items', async () => {
  const r = await json(await post({ items: [{ sku: 'A', qty: 1 }, { sku: 'B', qty: 1 }] }))
  assert.equal(r.body.total, 50)
})

test('POST /orders with unknown sku yields total null', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — unpriced sku gives NaN, serialised as null, still 201
  const r = await json(await post({ items: [{ sku: 'ZZ', qty: 1 }] }))
  assert.equal(r.status, 201)
  assert.equal(r.body.total, null)
})

test('POST /orders with missing qty yields total null', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — no qty validation; NaN becomes null
  const r = await json(await post({ items: [{ sku: 'A' }] }))
  assert.equal(r.status, 201)
  assert.equal(r.body.total, null)
})

for (const [name, body, raw] of [
  ['missing items', {}],
  ['empty items', { items: [] }],
  ['items not an array', { items: 'x' }],
  ['empty body', undefined, ''],
  ['invalid JSON', undefined, '{nope'],
  ['JSON null', undefined, 'null'],
]) {
  test(`POST /orders 400 on ${name}`, async () => {
    assert.deepEqual(await json(await post(body, raw)), { status: 400, type: 'application/json', body: { error: 'items required' } })
  })
}

test('GET /orders/{id} returns a stored order', async () => {
  const r = await json(await fetch(`${base}/orders/1`))
  assert.deepEqual(r, { status: 200, type: 'application/json', body: { id: '1', items: [{ sku: 'A', qty: 2 }], total: 20 } })
})

test('GET /orders/{id} for an unknown id returns 200 with an error body', async () => {
